    [11] = {
      beijing = 4990,
      dialog = 3,
      music = "PW_5_Suspect",
      renwu = "npc",
      sentence = "He went up to an ancient shelf and quickly pulled out a large tome half the height of a person—the family tree of Victor's clan.",
